#!/bin/sh
# Runs ONCE, on the first start of an EMPTY staging data volume (MySQL entrypoint). Creates two least-privilege accounts:
#   meki_migrator — schema changes (prisma migrate deploy) and the seed; used only by operator one-off jobs
#   meki_app      — the running API: data access only (no DDL, no GRANT, no FILE, no SUPER)
# Passwords come from the container environment (generated by init-secrets.mjs); nothing is printed.
set -eu
mysql -uroot -p"$MYSQL_ROOT_PASSWORD" <<SQL
CREATE USER IF NOT EXISTS 'meki_migrator'@'%' IDENTIFIED BY '${MEKI_MIGRATOR_PASSWORD}';
GRANT SELECT, INSERT, UPDATE, DELETE, CREATE, ALTER, DROP, INDEX, REFERENCES, TRIGGER, CREATE VIEW, SHOW VIEW, LOCK TABLES ON \`meki_staging\`.* TO 'meki_migrator'@'%';
CREATE USER IF NOT EXISTS 'meki_app'@'%' IDENTIFIED BY '${MEKI_APP_DB_PASSWORD}';
GRANT SELECT, INSERT, UPDATE, DELETE ON \`meki_staging\`.* TO 'meki_app'@'%';
FLUSH PRIVILEGES;
SQL
